-- Abstract, no table emitted: Party

CREATE TABLE IF NOT EXISTS Car (
  vin VARCHAR NOT NULL,
  seats BIGINT,
  PRIMARY KEY (vin)
);

CREATE TABLE IF NOT EXISTS Company (
  vat VARCHAR,
  id VARCHAR NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS Person (
  email VARCHAR NOT NULL UNIQUE,
  born DATE,
  createdAt TIMESTAMP NOT NULL,
  id VARCHAR NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS KNOWS (
  src_id VARCHAR NOT NULL,
  dst_id VARCHAR NOT NULL,
  since DATE,
  FOREIGN KEY (src_id) REFERENCES Person (id),
  FOREIGN KEY (dst_id) REFERENCES Person (id)
);

CREATE TABLE IF NOT EXISTS LIKES (
  src_id VARCHAR NOT NULL,
  dst_id VARCHAR NOT NULL,
  FOREIGN KEY (src_id) REFERENCES Person (id),
  FOREIGN KEY (dst_id) REFERENCES Company (id)
);

-- 'Party' and/or 'Car' are abstract; this is the Company → Car pair.
CREATE TABLE IF NOT EXISTS OWNS_Company_Car (
  src_id VARCHAR NOT NULL,
  dst_vin VARCHAR NOT NULL,
  since DATE,
  FOREIGN KEY (src_id) REFERENCES Company (id),
  FOREIGN KEY (dst_vin) REFERENCES Car (vin)
);

-- 'Party' and/or 'Car' are abstract; this is the Person → Car pair.
CREATE TABLE IF NOT EXISTS OWNS_Person_Car (
  src_id VARCHAR NOT NULL,
  dst_vin VARCHAR NOT NULL,
  since DATE,
  FOREIGN KEY (src_id) REFERENCES Person (id),
  FOREIGN KEY (dst_vin) REFERENCES Car (vin)
);

